    let msg = item.json.message;

    // String in gültiges JSON umwandeln
    // erstens, evtl. fehlende Kommas und unnötige Leerzeichen korrigieren
    msg = msg.replace(/,\s*\n\s*"/g, ',\n"') // korrigiert evtl. fehlende Kommas
             .replace(/\n\s*}/g, '\n}');    // korrigiert Zeilenende

    // JSON parsen
    let parsed;
    try {
        parsed = JSON.parse(msg);
    } catch (e) {
        // Falls Parsing fehlschlägt
        parsed = { error: "Parsing failed", raw: msg };
    }

    return {
        json: {
            topic: item.json.topic, // original topic behalten
            ...parsed               // alle Felder aus der Message
        }
    };
});

// Alle JSON-Daten holen
const raw = items.map(i => i.json);

// Nach sensor_id gruppieren
const bySensor = {};
for (const row of raw) {
  const sid = row.sensor_id;
  if (!bySensor[sid]) {
    bySensor[sid] = [];
  }
  bySensor[sid].push(row);
}

const results = [];

for (const sensorId of Object.keys(bySensor)) {
  const data = bySensor[sensorId];

  // Nach Zeit sortieren (älteste zuerst)
  data.sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime());

  // Wenn aus irgendeinem Grund keine Daten da sind, überspringen
  if (data.length === 0) continue;

  // Variablen für Berechnung
  let totalFill = 0;
  let totalHours = 0;
  let lastLevel = data[0].fill_level;
  let lastTime = new Date(data[0].created_at);

  for (let i = 1; i < data.length; i++) {
    const currLevel = data[i].fill_level;
    const currTime = new Date(data[i].created_at);

    // Wenn signifikanter Abfall erkannt → Entleerung, starte neu
    if (currLevel < lastLevel - 20) { // z. B. Abfall >20% → Müll wurde geleert
      lastLevel = currLevel;
      lastTime = currTime;
      continue;
    }

    // Nur positive Steigerung berücksichtigen
    const diff = currLevel - lastLevel;
    const hours = (currTime.getTime() - lastTime.getTime()) / (1000 * 3600);

    if (diff > 0 && hours > 0) {
      totalFill += diff;
      totalHours += hours;
    }

    lastLevel = currLevel;
    lastTime = currTime;
  }

  // Füllrate pro Stunde
  const fillRatePerHour = totalHours > 0 ? totalFill / totalHours : 0;

  // Letzter Füllstand / letzte Zeile für diesen Sensor
  const lastEntry = data[data.length - 1];
  const currentLevel = lastEntry.fill_level;

  // Geschätzte Zeit bis voll
  const estimatedHoursToFull =
    fillRatePerHour > 0 ? (100 - currentLevel) / fillRatePerHour : null;

  // Ergebnis für diesen Sensor pushen
  results.push({
    json: {
      sensor_id: sensorId,
      current_fill: currentLevel,
      fill_rate_per_hour: fillRatePerHour,
      estimated_hours_to_full: estimatedHoursToFull,
      location: lastEntry.location,
      type: lastEntry.type,
    },
  });
}

// Alle Sensor-Ergebnisse zurückgeben
return results;

