// Alle Inputdaten holen
const items = $input.all();

// Sensor-IDs sammeln
let allSensors = [];

for (const item of items) {
  let data = item.json;

  // Falls die Daten in einer Property wie 'data' stecken
  if (data.data) data = data.data;

  // Falls data als String kommt → JSON parsen
  if (typeof data === 'string') {
    try {
      data = JSON.parse(data);
    } catch (e) {
      throw new Error('Fehler beim Parsen von JSON: ' + e.message);
    }
  }

  // Einzelnes Objekt in Array packen
  if (!Array.isArray(data)) data = [data];

  // Sensor-IDs extrahieren
  for (const entry of data) {
    if (entry.sensor_id) allSensors.push(entry.sensor_id);
  }
}

// Duplikate entfernen
const uniqueSensors = [...new Set(allSensors)];

// Ergebnis zurückgeben – ready für PostgreSQL jsonb
return [{
  json: {
    affected_bins: uniqueSensors
  }
}];

